 29→func newAttachCmd() *cobra.Command {
 30→	var (
 31→		force     bool
 32→		agentFlag string
 33→	)
 34→	cmd := &cobra.Command{
 35→		Use:   "attach <session-id>",
 36→		Short: "Attach an existing agent session",
 37→		Long: `Attach an existing agent session that wasn't captured by hooks.
 38→
 39→This creates a checkpoint from the session's transcript and registers the
 40→session for future tracking. Use this when hooks failed to fire or weren't
 41→installed when the session started.
 42→
 43→Supported agents: claude-code, gemini, opencode, cursor, copilot-cli, factoryai-droid`,
 44→		Args: cobra.ExactArgs(1),
 45→		RunE: func(cmd *cobra.Command, args []string) error {
 46→			if checkDisabledGuard(cmd.Context(), cmd.OutOrStdout()) {
 47→				return nil
 48→			}
 49→			agentName := types.AgentName(agentFlag)
 50→			return runAttach(cmd.Context(), cmd.OutOrStdout(), args[0], agentName, force)
 51→		},
 52→	}
 53→	cmd.Flags().BoolVarP(&force, "force", "f", false, "Skip confirmation and amend the last commit with the checkpoint trailer")
 54→	cmd.Flags().StringVarP(&agentFlag, "agent", "a", string(agent.DefaultAgentName), "Agent that created the session (claude-code, gemini, opencode, cursor, copilot-cli, factoryai-droid)")
 55→	return cmd
 56→}
 57→
 58→func runAttach(ctx context.Context, w io.Writer, sessionID string, agentName types.AgentName, force bool) error {
 59→	logCtx := logging.WithComponent(ctx, "attach")
 60→
 61→	// Validate session ID format
 62→	if err := validation.ValidateSessionID(sessionID); err != nil {
 63→		return fmt.Errorf("invalid session ID: %w", err)
 64→	}
 65→
 66→	// Ensure we're in a git repo
 67→	repoRoot, err := paths.WorktreeRoot(ctx)
 68→	if err != nil {
 69→		return fmt.Errorf("not a git repository: %w", err)
 70→	}
 71→
 72→	// Check session isn't already tracked
 73→	store, err := session.NewStateStore(ctx)
 74→	if err != nil {
 75→		return fmt.Errorf("failed to open session store: %w", err)
 76→	}
 77→	existing, err := store.Load(ctx, sessionID)
 78→	if err != nil {
 79→		return fmt.Errorf("failed to check existing session: %w", err)
 80→	}
 81→	if existing != nil {
 82→		return fmt.Errorf("session %s is already tracked by Entire", sessionID)
 83→	}
 84→
 85→	// Resolve agent and transcript path
 86→	ag, err := agent.Get(agentName)
 87→	if err != nil {
 88→		return fmt.Errorf("agent %q not available: %w", agentName, err)
 89→	}
 90→	agentType := ag.Type()
 91→
 92→	transcriptPath, err := resolveTranscriptPath(ctx, sessionID, ag)
 93→	if err != nil {
 94→		return fmt.Errorf("failed to resolve transcript path: %w", err)
 95→	}
 96→	// Agents use cwd-derived project directories, so the transcript may be stored under
 97→	// a different project directory if the session was started from a different working directory.
 98→	if _, statErr := os.Stat(transcriptPath); statErr != nil {
 99→		if found, searchErr := searchTranscriptInProjectDirs(agentName, sessionID, ag); searchErr == nil {
100→			logging.Info(logCtx, "found transcript in alternative project directory", "path", found)
101→			transcriptPath = found
102→		} else {
103→			logging.Debug(logCtx, "fallback transcript search failed", "error", searchErr)
104→		}
105→	}
106→	if _, statErr := os.Stat(transcriptPath); statErr != nil {
107→		return fmt.Errorf("transcript not found at %s; is the session ID correct?", transcriptPath)
108→	}
109→
110→	// Read transcript data
111→	transcriptData, err := ag.ReadTranscript(transcriptPath)
112→	if err != nil {
113→		return fmt.Errorf("failed to read transcript: %w", err)
114→	}
115→
116→	// Extract modified files from transcript
117→	var modifiedFiles []string
118→	if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok {
119→		if files, _, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptPath, 0); fileErr != nil {
120→			logging.Warn(logCtx, "failed to extract modified files from transcript", "error", fileErr)
121→		} else {
122→			modifiedFiles = files
123→		}
124→	}
125→
126→	// Detect file changes via git status (no pre-untracked filter since we don't know pre-state)
127→	changes, err := DetectFileChanges(ctx, nil)
128→	if err != nil {
129→		logging.Warn(logCtx, "failed to detect file changes, checkpoint may be incomplete", "error", err)
130→	}
131→
132→	// Filter and normalize paths
133→	relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
134→	var relNewFiles, relDeletedFiles []string
135→	if changes != nil {
136→		relNewFiles = FilterAndNormalizePaths(changes.New, repoRoot)
137→		relDeletedFiles = FilterAndNormalizePaths(changes.Deleted, repoRoot)
138→		relModifiedFiles = mergeUnique(relModifiedFiles, FilterAndNormalizePaths(changes.Modified, repoRoot))
139→	}
140→
141→	// Filter to uncommitted files only
142→	relModifiedFiles = filterToUncommittedFiles(ctx, relModifiedFiles, repoRoot)
143→
144→	if err := strategy.EnsureSetup(ctx); err != nil {
145→		return fmt.Errorf("failed to set up strategy: %w", err)
146→	}
147→
148→	// Create session metadata directory and copy transcript
149→	sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
150→	sessionDirAbs, err := paths.AbsPath(ctx, sessionDir)
151→	if err != nil {
152→		return fmt.Errorf("failed to resolve session directory path: %w", err)
153→	}
154→	if err := os.MkdirAll(sessionDirAbs, 0o750); err != nil {
155→		return fmt.Errorf("failed to create session directory: %w", err)
156→	}
157→	logFile := filepath.Join(sessionDirAbs, paths.TranscriptFileName)
158→	if err := os.WriteFile(logFile, transcriptData, 0o600); err != nil {
159→		return fmt.Errorf("failed to write transcript: %w", err)
160→	}
161→
162→	// Get git author
163→	author, err := GetGitAuthor(ctx)
164→	if err != nil {
165→		return fmt.Errorf("failed to get git author: %w", err)
166→	}
167→
168→	// Extract first prompt from transcript for the commit message
169→	firstPrompt := extractFirstPromptFromTranscript(transcriptData)
170→	commitMessage := generateCommitMessage(firstPrompt, agentType)
171→
172→	// Initialize session state BEFORE SaveStep so it exists when SaveStep loads it
173→	strat := GetStrategy(ctx)
174→	if err := strat.InitializeSession(ctx, sessionID, agentType, transcriptPath, firstPrompt, ""); err != nil {
175→		return fmt.Errorf("failed to initialize session: %w", err)
176→	}
177→
178→	// Update the session state with attach-specific metadata
179→	state, err := strategy.LoadSessionState(ctx, sessionID)
180→	if err != nil {
181→		return fmt.Errorf("failed to load session state: %w", err)
182→	}
183→	if state == nil {
184→		return fmt.Errorf("session state not found after initialization (session_id=%s)", sessionID)
185→	}
186→	state.CLIVersion = versioninfo.Version
187→	state.TranscriptPath = transcriptPath
188→	if err := strategy.SaveSessionState(ctx, state); err != nil {
189→		return fmt.Errorf("failed to save session state: %w", err)
190→	}
191→
192→	// Build step context and save checkpoint
193→	totalChanges := len(relModifiedFiles) + len(relNewFiles) + len(relDeletedFiles)
194→
195→	stepCtx := strategy.StepContext{
196→		SessionID:      sessionID,
197→		ModifiedFiles:  relModifiedFiles,
198→		NewFiles:       relNewFiles,
199→		DeletedFiles:   relDeletedFiles,
200→		MetadataDir:    sessionDir,
201→		MetadataDirAbs: sessionDirAbs,
202→		CommitMessage:  commitMessage,
203→		TranscriptPath: transcriptPath,
204→		AuthorName:     author.Name,
205→		AuthorEmail:    author.Email,
206→		AgentType:      agentType,
207→	}
208→
209→	if err := strat.SaveStep(ctx, stepCtx); err != nil {
210→		return fmt.Errorf("failed to save checkpoint: %w", err)
211→	}
212→
213→	checkpointIDStr, condenseErr := condenseAndFinalizeSession(logCtx, strat, sessionID)
214→
215→	// Print confirmation
216→	fmt.Fprintf(w, "Attached session %s\n", sessionID)
217→	if totalChanges > 0 {
218→		fmt.Fprintf(w, "  Checkpoint saved with %d file(s)\n", totalChanges)
219→	} else {
220→		fmt.Fprintln(w, "  Checkpoint saved (transcript only, no uncommitted file changes detected)")
221→	}
222→	if condenseErr != nil {
223→		fmt.Fprintln(w, "  Warning: checkpoint saved on shadow branch only (condensation failed)")
224→	}
225→	fmt.Fprintln(w, "  Session is now tracked — future prompts will be captured automatically")
226→
227→	// Offer to amend the last commit with the checkpoint trailer
228→	if checkpointIDStr != "" {
229→		if err := promptAmendCommit(ctx, w, checkpointIDStr, force); err != nil {
230→			logging.Warn(logCtx, "failed to amend commit", "error", err)
231→			fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
232→		}
233→	}
234→
235→	return nil
236→}
