238→// condenseAndFinalizeSession condenses the session to permanent storage and transitions it to IDLE.
239→// Returns the checkpoint ID string and any condensation error.
240→func condenseAndFinalizeSession(ctx context.Context, strat *strategy.ManualCommitStrategy, sessionID string) (string, error) {
241→	var checkpointIDStr string
242→	var condenseErr error
243→	if err := strat.CondenseSessionByID(ctx, sessionID); err != nil {
244→		logging.Warn(ctx, "failed to condense session", "error", err, "session_id", sessionID)
245→		condenseErr = err
246→	}
247→
248→	// Single load serves both checkpoint ID extraction and finalization
249→	state, loadErr := strategy.LoadSessionState(ctx, sessionID)
250→	if loadErr != nil {
251→		logging.Warn(ctx, "failed to load session state after condensation", "error", loadErr, "session_id", sessionID)
252→		return checkpointIDStr, condenseErr
253→	}
254→	if state == nil {
255→		return checkpointIDStr, condenseErr
256→	}
257→
258→	if condenseErr == nil {
259→		checkpointIDStr = state.LastCheckpointID.String()
260→	}
261→
262→	now := time.Now()
263→	state.LastInteractionTime = &now
264→	if transErr := strategy.TransitionAndLog(ctx, state, session.EventTurnEnd, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
265→		logging.Warn(ctx, "failed to transition session to idle", "error", transErr, "session_id", sessionID)
266→	}
267→	if saveErr := strategy.SaveSessionState(ctx, state); saveErr != nil {
268→		logging.Warn(ctx, "failed to save session state after transition", "error", saveErr, "session_id", sessionID)
269→	}
270→
271→	return checkpointIDStr, condenseErr
272→}
