274→// promptAmendCommit shows the last commit and asks whether to amend it with the checkpoint trailer.
275→// When force is true, it amends without prompting.
276→func promptAmendCommit(ctx context.Context, w io.Writer, checkpointIDStr string, force bool) error {
277→	// Get HEAD commit info
278→	repo, err := openRepository(ctx)
279→	if err != nil {
280→		return fmt.Errorf("failed to open repository: %w", err)
281→	}
282→	headRef, err := repo.Head()
283→	if err != nil {
284→		return fmt.Errorf("failed to get HEAD: %w", err)
285→	}
286→	headCommit, err := repo.CommitObject(headRef.Hash())
287→	if err != nil {
288→		return fmt.Errorf("failed to get HEAD commit: %w", err)
289→	}
290→
291→	shortHash := headRef.Hash().String()[:7]
292→	subject := strings.SplitN(headCommit.Message, "\n", 2)[0]
293→
294→	// Check if the commit already has this checkpoint trailer
295→	if _, found := trailers.ParseCheckpoint(headCommit.Message); found {
296→		fmt.Fprintf(w, "\nLast commit already has an Entire-Checkpoint trailer.\n")
297→		return nil
298→	}
299→
300→	fmt.Fprintf(w, "\nLast commit: %s %s\n", shortHash, subject)
301→
302→	amend := true
303→	if !force {
304→		form := NewAccessibleForm(
305→			huh.NewGroup(
306→				huh.NewConfirm().
307→					Title("Amend the last commit in this branch?").
308→					Affirmative("Y").
309→					Negative("n").
310→					Value(&amend),
311→			),
312→		)
313→		if err := form.Run(); err != nil {
314→			return fmt.Errorf("prompt failed: %w", err)
315→		}
316→	}
317→
318→	if !amend {
319→		fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
320→		return nil
321→	}
322→
323→	// Amend the commit with the checkpoint trailer
324→	newMessage := fmt.Sprintf("%s\n\n%s: %s\n", strings.TrimRight(headCommit.Message, "\n"), trailers.CheckpointTrailerKey, checkpointIDStr)
325→
326→	cmd := exec.CommandContext(ctx, "git", "commit", "--amend", "-m", newMessage)
327→	if output, err := cmd.CombinedOutput(); err != nil {
328→		return fmt.Errorf("failed to amend commit: %w\n%s", err, output)
329→	}
330→
331→	fmt.Fprintf(w, "Amended commit %s with Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
332→	return nil
333→}
