335→// extractFirstPromptFromTranscript reads transcript bytes and returns the first user prompt.
336→func extractFirstPromptFromTranscript(data []byte) string {
337→	lines, err := transcript.ParseFromBytes(data)
338→	if err != nil {
339→		return ""
340→	}
341→	for _, line := range lines {
342→		if line.Type == transcript.TypeUser {
343→			prompt := extractTextFromMessage(line.Message)
344→			if prompt != "" {
345→				return prompt
346→			}
347→		}
348→	}
349→	return ""
350→}
351→
352→// extractTextFromMessage extracts the text content from a transcript message.
353→func extractTextFromMessage(msg json.RawMessage) string {
354→	// Try string content first (simple user messages)
355→	var simple struct {
356→		Content string `json:"content"`
357→	}
358→	if err := json.Unmarshal(msg, &simple); err == nil && simple.Content != "" {
359→		return simple.Content
360→	}
361→
362→	// Try array content (messages with tool results, text blocks, etc.)
363→	var array struct {
364→		Content []struct {
365→			Type string `json:"type"`
366→			Text string `json:"text"`
367→		} `json:"content"`
368→	}
369→	if err := json.Unmarshal(msg, &array); err == nil {
370→		for _, block := range array.Content {
371→			if block.Type == "text" && block.Text != "" {
372→				return block.Text
373→			}
374→		}
375→	}
376→
377→	return ""
378→}
