// extractFirstPromptFromTranscript reads transcript bytes and returns the first user prompt.
// Supports both JSONL format (Claude Code, Cursor, OpenCode) and Gemini JSON format.
func extractFirstPromptFromTranscript(data []byte) string {
	// Try JSONL format first (Claude Code, Cursor, OpenCode, etc.)
	lines, err := transcript.ParseFromBytes(data)
	if err == nil {
		for _, line := range lines {
			if line.Type == transcript.TypeUser {
				prompt := extractTextFromMessage(line.Message)
				if prompt != "" {
					return prompt
				}
			}
		}
	}

	// Fallback: try Gemini JSON format {"messages": [...]}
	if prompts, gemErr := geminicli.ExtractAllUserPrompts(data); gemErr == nil && len(prompts) > 0 {
		return prompts[0]
	}

	return ""
}
```

