// extractModelFromTranscript extracts the model name from a JSONL transcript.
// Best-effort: returns empty string if the transcript format doesn't include model info
// (e.g., Gemini stores model info in hook events, not the transcript).
func extractModelFromTranscript(data []byte) string {
	lines, err := transcript.ParseFromBytes(data)
	if err != nil {
		return ""
	}

	for _, line := range lines {
		if line.Type != transcript.TypeAssistant {
			continue
		}
		var msg struct {
			Model string `json:"model"`
		}
		if err := json.Unmarshal(line.Message, &msg); err == nil && msg.Model != "" {
			return msg.Model
		}
	}
	return ""
}
