// estimateSessionDuration estimates session duration in milliseconds from JSONL transcript timestamps.
// Returns 0 if timestamps are not available (e.g., Gemini transcripts).
func estimateSessionDuration(data []byte) int64 {
	lines, err := transcript.ParseFromBytes(data)
	if err != nil || len(lines) == 0 {
		return 0
	}

	type timestamped struct {
		Timestamp string `json:"timestamp"`
	}

	var first, last time.Time
	for _, line := range lines {
		var ts timestamped
		if err := json.Unmarshal(line.Message, &ts); err != nil || ts.Timestamp == "" {
			continue
		}
		t, err := time.Parse(time.RFC3339Nano, ts.Timestamp)
		if err != nil {
			// Try alternate format without nanoseconds
			t, err = time.Parse("2006-01-02T15:04:05.000Z", ts.Timestamp)
			if err != nil {
				continue
			}
		}
		if first.IsZero() {
			first = t
		}
		last = t
	}

	if first.IsZero() || last.IsZero() || !last.After(first) {
		return 0
	}
	return last.Sub(first).Milliseconds()
}
