// countUserTurns counts real user prompts in a transcript (excluding tool_result messages).
// Supports both JSONL format (Claude Code, Cursor) and Gemini JSON format.
func countUserTurns(data []byte) int {
	// Try JSONL format first — use extractTextFromMessage to distinguish
	// real user prompts from tool_result messages (both have type "user").
	lines, err := transcript.ParseFromBytes(data)
	if err == nil {
		count := 0
		for _, line := range lines {
			if line.Type == transcript.TypeUser {
				if extractTextFromMessage(line.Message) != "" {
					count++
				}
			}
		}
		if count > 0 {
			return count
		}
	}

	// Fallback: Gemini JSON format
	if prompts, gemErr := geminicli.ExtractAllUserPrompts(data); gemErr == nil {
		return len(prompts)
	}

	return 0
}

// extractModelFromTranscript extracts the model name from a JSONL transcript.
// Best-effort: returns empty string if the transcript format doesn't include model info
// (e.g., Gemini stores model info in hook events, not the transcript).
func extractModelFromTranscript(data []byte) string {
	lines, err := transcript.ParseFromBytes(data)
	if err != nil {
		return ""
	}

	for _, line := range lines {
		if line.Type != transcript.TypeAssistant {
			continue
		}
		var msg struct {
			Model string `json:"model"`
		}
		if err := json.Unmarshal(line.Message, &msg); err == nil && msg.Model != "" {
			return msg.Model
		}
	}
	return ""
}

// estimateSessionDuration estimates session duration in milliseconds from JSONL transcript timestamps.
// The "timestamp" field is a top-level field in JSONL lines (alongside "type", "uuid", "message"),
// NOT inside the "message" object. We parse raw lines since transcript.Line doesn't capture it.
// Returns 0 if timestamps are not available (e.g., Gemini transcripts).
func estimateSessionDuration(data []byte) int64 {
	type timestamped struct {
		Timestamp string `json:"timestamp"`
	}

	var first, last time.Time
	for _, rawLine := range bytes.Split(data, []byte("\n")) {
		if len(rawLine) == 0 {
			continue
		}
		var ts timestamped
		if err := json.Unmarshal(rawLine, &ts); err != nil || ts.Timestamp == "" {
			continue
		}
		t, err := time.Parse(time.RFC3339Nano, ts.Timestamp)
		if err != nil {
			t, err = time.Parse(time.RFC3339, ts.Timestamp)
			if err != nil {
				continue
			}
		}
		if first.IsZero() {
			first = t
		}
		last = t
	}

	if first.IsZero() || last.IsZero() || !last.After(first) {
		return 0
	}
	return last.Sub(first).Milliseconds()
}

