// resolveAgentAndTranscript tries to find the transcript for the given session ID.
// It first tries the specified agent, then falls back to searching all registered agents.
// Returns the resolved agent, agent name, transcript path, and any error.
func resolveAgentAndTranscript(ctx context.Context, sessionID string, preferredAgent types.AgentName) (agent.Agent, types.AgentName, string, error) {
	// Try the preferred agent first
	if path, ag, err := tryResolveTranscript(ctx, sessionID, preferredAgent); err == nil {
		return ag, preferredAgent, path, nil
	}

	// Auto-detect: try all other registered agents
	for _, name := range agent.List() {
		if name == preferredAgent {
			continue
		}
		if path, ag, err := tryResolveTranscript(ctx, sessionID, name); err == nil {
			logging.Info(ctx, "auto-detected agent from transcript", "agent", name, "path", path)
			return ag, name, path, nil
		}
	}

	return nil, "", "", fmt.Errorf("transcript not found for session %s with any agent; try --agent to specify", sessionID)
}

// tryResolveTranscript attempts to find a transcript for the given session ID using the specified agent.
func tryResolveTranscript(ctx context.Context, sessionID string, agentName types.AgentName) (string, agent.Agent, error) {
	ag, err := agent.Get(agentName)
	if err != nil {
		return "", nil, err
	}

	// Try direct resolution
	transcriptPath, err := resolveTranscriptPath(ctx, sessionID, ag)
	if err == nil {
		if _, statErr := os.Stat(transcriptPath); statErr == nil {
			return transcriptPath, ag, nil
		}
	}

	// Try searching project directories
	if found, searchErr := searchTranscriptInProjectDirs(agentName, sessionID, ag); searchErr == nil {
		return found, ag, nil
	}

	return "", nil, fmt.Errorf("transcript not found for agent %s", agentName)
}

